func (this *Composite) snapshotToDrawAfterChildren_(handle int64, snapshot int64) {
}

func (this *Composite) string_() string {
	return fmt.Sprintf("%s [layout=%v]", this.Scrollable.string_(), this.layout)
}

func (this *Composite) translateMnemonic_(event *Event, control *Control) bool {
	if this.Scrollable.translateMnemonic_(event, control) {
		return true
	}
	if control != (nil) {
		for _, child := range this.impl._getChildren_() {
			if child.impl.translateMnemonic_(event, control) {
				return true
			}
		}
	}
	return false
}

func (this *Composite) translateTraversalEvent_(event int64) bool {
	if this.socketHandle != 0 {
		return false
	}
	return this.Scrollable.translateTraversalEvent_(event)
}

func (this *Composite) traversalCode_(key int32, event int64) int32 {
	if (this.state & WidgetCANVAS) != 0 {
		if (this.style & NO_FOCUS) != 0 {
			return 0
		}
		if this.HooksKeys() {
			return 0
		}
	}
	return this.Scrollable.traversalCode_(key, event)
}

func (this *Composite) updateBackgroundMode_() {
	this.Scrollable.updateBackgroundMode_()
	for _, child := range this.impl._getChildren_() {
		child.impl.updateBackgroundMode_()
	}
}
